// Writes supabase/003_lehenga_catalog.sql from lib/catalog.mjs.  Run: node scripts/catalog-sql.mjs
import { writeFileSync } from 'node:fs';
import { CATEGORIES, PRODUCTS } from '../lib/catalog.mjs';

const q = s => (s == null ? 'null' : `'${String(s).replace(/'/g, "''")}'`);
const arr = a => (a.length ? `array[${a.map(q).join(',')}]` : `'{}'::text[]`);

const sql = `-- Lehenga & half-saree collection. Paste into Supabase → SQL Editor → Run (safe to re-run).
-- Generated by scripts/catalog-sql.mjs from lib/catalog.mjs.

insert into public.categories (name, slug, sort, bg, w1, w2) values
${CATEGORIES.map(c => ` (${q(c.name)},${q(c.slug)},${c.sort},${q(c.bg)},${q(c.w1)},${q(c.w2)})`).join(',\n')}
on conflict (slug) do update set name = excluded.name, sort = excluded.sort;

insert into public.products (slug,name,description,category_id,price,was_price,stock,variant_label,variants,images,featured)
select v.slug,v.name,v.descr,c.id,v.price,v.was,v.stock,v.vl,v.vars,v.imgs,v.feat
from (values
${PRODUCTS.map(p => ` (${q(p.slug)},${q(p.name)},${q(p.description)},${q(p.category.slug)},${p.price},${p.was_price ?? 'null::int'},${p.stock},${q(p.variant_label)},${arr(p.variants)},${arr(p.images)},${p.featured})`).join(',\n')}
) v(slug,name,descr,cat,price,was,stock,vl,vars,imgs,feat)
join public.categories c on c.slug = v.cat
on conflict (slug) do update set name = excluded.name, description = excluded.description, category_id = excluded.category_id,
  price = excluded.price, images = excluded.images, featured = excluded.featured;
`;
writeFileSync(new URL('../supabase/003_lehenga_catalog.sql', import.meta.url), sql);
console.log(`Wrote ${PRODUCTS.length} products`);
